constexpr uint32_t sticky=0x80000000u;
void require(bool x,const std::string &s){if(!x)throw std::runtime_error(s);}
uint16_t bf16(float x){const auto b=std::bit_cast<uint32_t>(x);return uint16_t((b+0x7fff+((b>>16)&1))>>16);}
float number(uint16_t x){return std::bit_cast<float>(uint32_t(x)<<16);}
uint32_t env(const char *key,uint32_t fallback,uint32_t limit){const char *r=std::getenv(key);if(!r)return fallback;size_t used=0;auto x=std::stoul(r,&used);require(used==std::strlen(r) && x && x<=limit,std::string("invalid ")+key);return uint32_t(x);}
struct Guard{MetalBuffer allocation;uint64_t bytes;bool clean()const{const auto *p=static_cast<const uint8_t *>(allocation.contents());return std::all_of(p+bytes,p+bytes+64,[](uint8_t x){return x==0x5a;});}};
MetalBuffer buffer(MetalBackend &b,uint64_t n,std::vector<Guard> &guards){auto a=b.allocateBuffer(n+64,splash::metal::BufferStorage::Shared,"private small F32 MoE guarded");std::memset(a.contents(),0xa5,n);std::memset(static_cast<uint8_t *>(a.contents())+n,0x5a,64);guards.push_back({a,n});return b.view(a,0,n);}
template<class T>MetalBuffer upload(MetalBackend &b,const std::vector<T> &v,const char *name){auto a=b.allocateBuffer(v.size()*sizeof(T),splash::metal::BufferStorage::Shared,name);std::memcpy(a.contents(),v.data(),v.size()*sizeof(T));return a;}
void equal(const MetalBuffer &a,const MetalBuffer &b,uint64_t n,const char *what){require(a.sizeBytes()>=n && b.sizeBytes()>=n,std::string("short ")+what);if(std::memcmp(a.contents(),b.contents(),n)){const auto *x=static_cast<const uint8_t *>(a.contents()),*y=static_cast<const uint8_t *>(b.contents());uint64_t i=0;while(i<n && x[i]==y[i])++i;throw std::runtime_error(std::string("exact byte mismatch ")+what+" at "+std::to_string(i));}}
std::vector<FlashSmallMoEF32Job> referenceJobs(std::span<const int64_t> ids,uint32_t gr){std::vector<FlashSmallMoEF32Job> result;std::vector<bool> used(ids.size());for(uint32_t first=0;first<ids.size();++first){if(used[first])continue;FlashSmallMoEF32Job j{ids[first],0,{UINT32_MAX,UINT32_MAX,UINT32_MAX,UINT32_MAX},0};for(uint32_t r=first;r<ids.size() && j.route_count<gr;++r)if(!used[r] && ids[r]==j.expert){j.routes[j.route_count++]=r;used[r]=true;}result.push_back(j);}return result;}
void cpu(){for(uint32_t values:{8u,16u}){const uint32_t k=values==8?640:2560;std::vector<uint32_t> seen(k);for(uint32_t lane=0;lane<32;++lane){std::vector<uint32_t> old,newer;for(uint32_t block=0;block<k;block+=values*32){const uint32_t origin=block+lane*values;if(origin>=k)continue;for(uint32_t j=0;j<values;++j){old.push_back(origin+j);++seen[origin+j];}for(uint32_t pack=0;pack<values/8;++pack)for(uint32_t j=0;j<8;++j)newer.push_back(origin+pack*8+j);}require(old==newer,"per-lane F32 K/reduction order changed");}require(std::all_of(seen.begin(),seen.end(),[](uint32_t x){return x==1;}),"K lane coverage differs");}
 for(uint32_t rows:{1u,4u,8u,16u})for(uint32_t gr:{1u,2u,4u}){std::vector<int64_t> ids(rows*10);for(uint32_t r=0;r<ids.size();++r)ids[r]=(r%13==0)?-1:(r*7)%31;auto jobs=referenceJobs(ids,gr);std::vector<uint32_t> seen(ids.size());for(const auto &j:jobs){require(j.route_count && j.route_count<=gr,"group count wrong");for(uint32_t i=0;i<j.route_count;++i){require(ids[j.routes[i]]==j.expert,"group owns wrong expert");++seen[j.routes[i]];}}require(std::all_of(seen.begin(),seen.end(),[](uint32_t x){return x==1;}),"group route bijection changed");}
 volatile float product=15.0f*number(0x3c01);const float coef=product-number(0x3d00);require(coef!=number(bf16(coef)),"F32 coefficient trap is BF16-representable");}
std::string metadata(const char *path){id<MTLDevice> d=MTLCreateSystemDefaultDevice();require(d!=nil,"Metal device missing");NSError *error=nil;id<MTLLibrary> l=[d newLibraryWithURL:[NSURL fileURLWithPath:[NSString stringWithUTF8String:path]] error:&error];require(l!=nil,"private library missing");std::vector<std::string> names{"flash_small_moe_f32_jobs","flash_small_moe_reference_contig_k16_sg4_c2","flash_small_moe_reference_contig_k8_sg2_c4","flash_expert_qmv_contig_k16_sg4_c2","flash_expert_qmv_contig_k8_sg2_c4"};for(uint32_t gr:{1u,2u,4u})for(const char *phase:{"gate_up","down"})names.push_back(std::string("flash_small_moe_f32_")+phase+"_gr"+std::to_string(gr));std::ostringstream o;o<<"{\"device_max_tgm_bytes\":"<<d.maxThreadgroupMemoryLength<<",\"pipelines\":[";bool first=true;for(const auto &name:names){id<MTLFunction> f=[l newFunctionWithName:[NSString stringWithUTF8String:name.c_str()]];require(f!=nil,"missing "+name);id<MTLComputePipelineState> p=[d newComputePipelineStateWithFunction:f error:&error];const uint32_t threads=name=="flash_small_moe_f32_jobs"?256:name.find("down")!=std::string::npos || name.find("k8_")!=std::string::npos?64:128;require(p && p.threadExecutionWidth==32 && p.maxTotalThreadsPerThreadgroup>=threads && p.staticThreadgroupMemoryLength<=d.maxThreadgroupMemoryLength,"pipeline limits "+name);if(!first)o<<',';first=false;o<<"{\"name\":"<<splash::json::quote(name)<<",\"max_threads\":"<<p.maxTotalThreadsPerThreadgroup<<",\"tgm_bytes\":"<<p.staticThreadgroupMemoryLength<<'}';}o<<"]}";return o.str();}
struct Stage{MetalBuffer g,u,a,d,o,gf,uf,df,diag;};
void times(std::ostream &o,const std::vector<CommandTiming> &t,bool gpu){o<<'[';bool first=true;for(const auto &v:t){if(!first)o<<',';first=false;o<<(gpu?v.gpuSeconds:v.wallSeconds)*1000;}o<<']';}
void run(MetalBackend &b,const FlashWeights &w,uint32_t layer,uint32_t rows,uint32_t gr,const std::string &pattern,uint32_t pairs,std::ostream &o){const uint32_t routes=rows*10;std::vector<uint16_t> hidden(rows*2560);for(uint32_t i=0;i<hidden.size();++i)hidden[i]=bf16(float(int((i*73+i/2560*17)%257)-128)/512);std::vector<int64_t> ids(routes);for(uint32_t r=0;r<rows;++r)for(uint32_t s=0;s<10;++s)ids[r*10+s]=pattern=="concentrated"?s:(r*73+s*53)%512;
 const char *idFile=std::getenv("FLASH_SMALL_MOE_IDS");if(idFile){require(std::filesystem::file_size(idFile)==uint64_t(routes)*8,"ID fixture size");std::ifstream f(idFile,std::ios::binary);f.read(reinterpret_cast<char *>(ids.data()),ids.size()*8);require(bool(f),"ID fixture read");}
 const char *error=std::getenv("FLASH_SMALL_MOE_ERROR");uint32_t expected=sticky;if(error){const std::string e=error;if(e=="invalid_ids"){ids[0]=-1;ids.back()=512;expected|=5;}else if(e=="nonfinite"){hidden[17]=0x7f80;expected|=4;}else throw std::runtime_error("error fixture must be invalid_ids/nonfinite");}
 const auto input=upload(b,hidden,"small MoE hidden"),expertIds=upload(b,ids,"small MoE original IDs");std::vector<uint16_t> weights(routes);for(uint32_t r=0;r<routes;++r)weights[r]=bf16(float(r%10+1)/55);const auto route=upload(b,weights,"unequal routing weights"),shared=upload(b,std::vector<uint16_t>(rows*2560,0),"shared zeros"),sharedGate=upload(b,std::vector<uint16_t>(rows,0),"shared gate zeros");
 const auto prefix="language_model.model.layers."+std::to_string(layer)+".mlp.switch_mlp";const auto &g=w.projection(prefix+".gate_proj"),&u=w.projection(prefix+".up_proj"),&d=w.projection(prefix+".down_proj");std::vector<Guard> guards;std::array<Stage,3> s;for(auto &v:s){v.g=buffer(b,uint64_t(routes)*640*2,guards);v.u=buffer(b,uint64_t(routes)*640*2,guards);v.a=buffer(b,uint64_t(routes)*640*2,guards);v.d=buffer(b,uint64_t(routes)*2560*2,guards);v.o=buffer(b,uint64_t(rows)*2560*2,guards);v.gf=buffer(b,uint64_t(routes)*640*4,guards);v.uf=buffer(b,uint64_t(routes)*640*4,guards);v.df=buffer(b,uint64_t(routes)*2560*4,guards);v.diag=buffer(b,4,guards);*static_cast<uint32_t *>(v.diag.contents())=sticky;}
 auto scratch=cand::allocateSmallMoEF32Scratch(b,rows);scratch.jobs=buffer(b,scratch.jobs.sizeBytes(),guards);scratch.count=buffer(b,4,guards);std::array<CommandGraph,3> graph;CommandGraph timed;
 addGatheredAffine(graph[0],input,g,expertIds,s[0].g,s[0].diag,rows,10);addGatheredAffine(graph[0],input,u,expertIds,s[0].u,s[0].diag,rows,10);addSiLUMultiply(graph[0],s[0].g,s[0].u,s[0].a,s[0].diag,rows,640,10);addGatheredAffine(graph[0],s[0].a,d,expertIds,s[0].d,s[0].diag,rows,10,true);
 cand::addSmallMoEF32Reference(graph[1],input,g,expertIds,s[1].g,s[1].gf,s[1].diag,rows,false);cand::addSmallMoEF32Reference(graph[1],input,u,expertIds,s[1].u,s[1].uf,s[1].diag,rows,false);addSiLUMultiply(graph[1],s[1].g,s[1].u,s[1].a,s[1].diag,rows,640,10);cand::addSmallMoEF32Reference(graph[1],s[1].a,d,expertIds,s[1].d,s[1].df,s[1].diag,rows,true);
 const auto candidate=[&](CommandGraph &q,bool taps){cand::addSmallMoEF32Jobs(q,expertIds,scratch,s[2].diag,rows,gr);cand::addSmallMoEF32Gate(q,input,g,u,expertIds,scratch,s[2].g,s[2].u,s[2].a,s[2].gf,s[2].uf,s[2].diag,rows,gr,taps);cand::addSmallMoEF32Down(q,s[2].a,d,expertIds,scratch,s[2].d,s[2].df,s[2].diag,rows,gr,taps);addCombine(q,s[2].d,expertIds,route,shared,sharedGate,s[2].o,s[2].diag,rows,2560,512,10);};candidate(graph[2],true);candidate(timed,false);
 for(uint32_t i=0;i<2;++i)addCombine(graph[i],s[i].d,expertIds,route,shared,sharedGate,s[i].o,s[i].diag,rows,2560,512,10);for(const auto &q:graph)(void)b.submitCommand(q.dispatches());
 const auto check=[&]{for(uint32_t i=1;i<3;++i){equal(s[0].g,s[i].g,uint64_t(routes)*640*2,"gate BF16");equal(s[0].u,s[i].u,uint64_t(routes)*640*2,"up BF16");equal(s[0].a,s[i].a,uint64_t(routes)*640*2,"activation BF16");equal(s[0].d,s[i].d,uint64_t(routes)*2560*2,"down BF16");equal(s[0].o,s[i].o,uint64_t(rows)*2560*2,"combine BF16");}equal(s[1].gf,s[2].gf,uint64_t(routes)*640*4,"gate F32 canonical sum");equal(s[1].uf,s[2].uf,uint64_t(routes)*640*4,"up F32 canonical sum");equal(s[1].df,s[2].df,uint64_t(routes)*2560*4,"down F32 canonical sum");for(const auto &v:s)require(*static_cast<const uint32_t *>(v.diag.contents())==expected,"independent sticky diagnostics differ");for(const auto &v:guards)require(v.clean(),"output/job/count guard changed");};check();
 const auto jobs=referenceJobs(ids,gr);if(gr>1){require(*static_cast<const uint32_t *>(scratch.count.contents())==jobs.size(),"GPU tiny job count");const auto *actual=static_cast<const FlashSmallMoEF32Job *>(scratch.jobs.contents());for(uint32_t i=0;i<routes;++i){const FlashSmallMoEF32Job want=i<jobs.size()?jobs[i]:FlashSmallMoEF32Job{-1,0,{UINT32_MAX,UINT32_MAX,UINT32_MAX,UINT32_MAX},0};require(std::memcmp(actual+i,&want,32)==0,"independent stable tiny job record differs");}}
 std::array<std::vector<CommandTiming>,2> t;for(uint32_t p=0;p<pairs;++p)for(uint32_t order=0;order<2;++order){const uint32_t which=(p+order)%2;auto v=b.submitCommand(which?timed.dispatches():graph[0].dispatches());require(std::isfinite(v.gpuSeconds) && std::isfinite(v.wallSeconds) && v.gpuSeconds>1e-9 && v.wallSeconds>1e-9,"nonpositive timing / stale ABI");t[which].push_back(v);check();}
 o<<"{\"layer\":"<<layer<<",\"rows\":"<<rows<<",\"group_rows\":"<<gr<<",\"pattern\":"<<splash::json::quote(error?error:idFile?"captured-routing/synthetic-hidden":pattern)<<",\"routes\":"<<routes<<",\"jobs\":"<<jobs.size()<<",\"all_bf16_stages_byte_exact\":true,\"all_f32_dot_sums_byte_exact\":true,\"independent_diagnostics\":"<<expected<<",\"guards_clean\":true,\"control_gpu_ms\":";times(o,t[0],true);o<<",\"candidate_gpu_ms\":";times(o,t[1],true);o<<",\"control_wall_ms\":";times(o,t[0],false);o<<",\"candidate_wall_ms\":";times(o,t[1],false);o<<'}';o.flush();}
}
int main(int argc,char **argv){@autoreleasepool{try{cpu();if(argc==2 && std::string(argv[1])=="--cpu-self-test"){std::cout<<"{\"pass\":true,\"gpu_work\":false,\"sizeof_command_timing\":"<<sizeof(CommandTiming)<<",\"checks\":[\"canonical_per_lane_K_order\",\"F32_non_BF16_coefficient\",\"stable_group_bijection_with_invalid_and_duplicate_IDs\"]}\n";return 0;}require(argc==4,"usage: small-moe-f32-oracle PRIVATE_LIBRARY ORIGINAL_PACKAGE REPORT");require(setenv("SPLASH_FLASH_EXPERT_QMV","1",1)==0 && setenv("SPLASH_FLASH_QMV_F32","1",1)==0,"cannot force v6 QMV policy");const auto meta=metadata(argv[1]);MetalBackend b(argv[1]);const auto w=FlashWeights::load(b,argv[2]);const uint32_t rows=env("FLASH_SMALL_MOE_ROWS",16,16),gr=env("FLASH_SMALL_MOE_GROUP",4,4),pairs=env("FLASH_SMALL_MOE_PAIRS",4,32);require(gr==1 || gr==2 || gr==4,"group must be1/2/4");uint32_t layer=0;if(const char *v=std::getenv("FLASH_SMALL_MOE_LAYER")){size_t used=0;auto x=std::stoul(v,&used);require(used==std::strlen(v) && x<48,"layer must be0..47");layer=uint32_t(x);}std::ofstream o(argv[3]);require(bool(o),"report unavailable");o<<std::setprecision(12)<<"{\"schema\":\"small-window-exact-f32-moe-v1\",\"pass\":true,\"sizeof_command_timing\":"<<sizeof(CommandTiming)<<",\"source\":"<<splash::json::quote(w.sourceIdentity())<<",\"manifest\":"<<splash::json::quote(w.manifestFingerprint())<<",\"current_math\":"<<splash::json::quote(flashAffineSemantics())<<",\"weight_conversion\":false,\"weight_operands\":\"original reconstructed F32\",\"pipeline_metadata\":"<<meta<<",\"timing_scope\":\"complete expert chain; grouped emitter included; F32 tap graph excluded\",\"cases\":[";bool first=true;for(const char *pattern:{"spread","concentrated"}){if(!first)o<<',';first=false;run(b,w,layer,rows,gr,pattern,pairs,o);if(std::getenv("FLASH_SMALL_MOE_IDS") || std::getenv("FLASH_SMALL_MOE_ERROR"))break;}o<<"]}\n";o.flush();require(bool(o),"report write");std::cout<<"{\"pass\":true,\"report\":"<<splash::json::quote(argv[3])<<"}\n";return 0;}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}}
